public static class Tests {
 static int passed;static string root;
 static void Check(bool condition,string name){if(!condition)throw new Exception("FAILED: "+name);Console.WriteLine("PASS "+name);passed++;}
 static void Reject(Action action,string name){try{action();}catch{Check(true,name);return;}throw new Exception("FAILED (accepted): "+name);}
 static string Dir(string name){string p=Path.Combine(root,name);Directory.CreateDirectory(p);return p;}
 [STAThread] public static int Main(string[] args){
  if(args.Length==2&&args[0]=="/delayed-stub"){Thread.Sleep(700);File.WriteAllText(args[1],"finished");return 0;}
  if(args.Length==2&&args[0]=="/stub"){File.WriteAllText(args[1],"uninstalled");return 0;}
  if(args.Length==3&&args[0]=="/remove-stub"){AppDomain.CurrentDomain.SetData("JingChu.SetupTestReg",args[2]);AppDomain.CurrentDomain.SetData("JingChu.SetupTestMenu",Path.Combine(args[1],"test-menu"));AppDomain.CurrentDomain.SetData("JingChu.SetupTestDesktop",Path.Combine(args[1],"test-desktop.lnk"));typeof(JingSetup.Program).GetMethod("Remove",BindingFlags.NonPublic|BindingFlags.Static).Invoke(null,new object[]{false});return 0;}
  try{
   if(args.Length!=1)throw new Exception("Usage: Tests.exe <isolated workspace directory>");
   root=Path.GetFullPath(args[0]);if(Directory.Exists(root))throw new Exception("Test directory must not already exist.");Directory.CreateDirectory(root);
   AppDomain.CurrentDomain.SetData("JingChu.TestData",Path.Combine(root,"data"));
   Engine.Log("SELFTEST START");
   Reject(()=>Engine.Validate(Path.GetPathRoot(root)),"drive root blocked");
   Reject(()=>Engine.Validate(Environment.GetFolderPath(Environment.SpecialFolder.UserProfile)),"profile root blocked");
   Reject(()=>Engine.Validate(Environment.GetFolderPath(Environment.SpecialFolder.Windows)+@"\Temp\x"),"Windows descendants blocked");
   Reject(()=>Engine.Validate(Environment.GetFolderPath(Environment.SpecialFolder.ProgramFiles)),"Program Files root blocked");
   Reject(()=>Engine.Validate(Path.Combine(root,@"a\..\b")),"relative components blocked");
   Reject(()=>Engine.Validate(Path.Combine(root,"a.txt:stream")),"alternate stream blocked");
   Reject(()=>Engine.Validate(@"\\.\PhysicalDrive0"),"device path blocked");
   Reject(()=>Engine.Validate(@"\\server\share"),"share root blocked");
   Reject(()=>Engine.Validate(Engine.DataDir),"backup directory protected");
   string unicode=Dir("中文 & ! % 测试"),file=Path.Combine(unicode,"readonly.txt");File.WriteAllText(file,"test");File.SetAttributes(file,FileAttributes.ReadOnly);
   Check(Engine.Describe(file).StartsWith("文件"),"file inspection");
   Check(Engine.Stats(unicode,CancellationToken.None).Contains("文件 1"),"size and count analysis");
   Check(Engine.Delete(unicode,false,false,CancellationToken.None,x=>{})==2&&!Directory.Exists(unicode),"readonly Unicode special-character tree deletion");
   string longRoot=Dir("long"),longDir=longRoot+"\\"+new string('a',110)+"\\"+new string('b',110)+"\\"+new string('c',110);
   // Create long and anomalous paths through native Win32, independent of .NET path normalization.
   CreateDirChain(longDir);
   string odd=longDir+@"\tail. ";WriteNative(odd);
   Check(Engine.Exists(odd),"trailing dot/space and extended path inspection");
   Engine.Delete(longRoot,false,false,CancellationToken.None,x=>{});Check(!Directory.Exists(longRoot),"long path and anomalous filename deletion");
   string keep=Dir("junction-target");File.WriteAllText(Path.Combine(keep,"keep.txt"),"keep");string link=Path.Combine(root,"junction-link"),outText;
   Check(Engine.Run(Environment.GetEnvironmentVariable("ComSpec"),"/c mklink /J "+Engine.Quote(link)+" "+Engine.Quote(keep),out outText)==0,"junction fixture creation");
   Engine.Delete(link,false,false,CancellationToken.None,x=>{});Check(File.Exists(Path.Combine(keep,"keep.txt"))&&!Engine.Exists(link),"junction destination preserved");
   string cancel=Dir("cancelled");var cts=new CancellationTokenSource();cts.Cancel();Reject(()=>Engine.Delete(cancel,false,false,cts.Token,x=>{}),"cancellation reported");Check(Directory.Exists(cancel),"cancelled target preserved");
   string move=Path.Combine(root,"move.txt"),dest=Path.Combine(root,"moved.txt");File.WriteAllText(move,"move");Engine.Rename(move,dest);Check(File.Exists(dest)&&!File.Exists(move),"rename/move");File.WriteAllText(move,"second");Reject(()=>Engine.Rename(move,dest),"move never overwrites existing target");
   string locked=Path.Combine(root,"locked.txt");File.WriteAllText(locked,"locked");using(var stream=new FileStream(locked,FileMode.Open,FileAccess.Read,FileShare.Read)){
    Reject(()=>Engine.Delete(locked,false,false,CancellationToken.None,x=>{}),"locked file reports failure");
    var lockers=Engine.Lockers(new[]{locked},CancellationToken.None);Check(lockers.Any(p=>p.process.pid==Process.GetCurrentProcess().Id),"Restart Manager identifies locking process");
   }
   Check(Engine.Delete(locked,false,false,CancellationToken.None,x=>{})==1,"deletion after releasing lock");
   ExtraTests();RegistryTests();InstallerTest();ButtonPaintTests();IconTests();StartupIconTests();UiTest();LogoTest();
 
   Console.WriteLine("TOTAL PASSED: "+passed);File.WriteAllText(Path.Combine(root,"RESULT.txt"),"TOTAL PASSED: "+passed+Environment.NewLine+"Admin ACL repair, real reboot deletion, interactive Recycle Bin, UAC and real third-party uninstall were not exercised.");return 0;
  }catch(Exception e){Console.Error.WriteLine(e);return 1;}
 }
 [System.Runtime.InteropServices.DllImport("kernel32.dll",CharSet=System.Runtime.InteropServices.CharSet.Unicode,SetLastError=true)]static extern bool CreateDirectoryW(string p,IntPtr sec);
 [System.Runtime.InteropServices.DllImport("kernel32.dll",CharSet=System.Runtime.InteropServices.CharSet.Unicode,SetLastError=true)]static extern IntPtr CreateFileW(string p,uint access,uint share,IntPtr sec,uint creation,uint flags,IntPtr template);
 [System.Runtime.InteropServices.DllImport("kernel32.dll")]static extern bool CloseHandle(IntPtr h);
 static void CreateDirChain(string p){string current=p.Substring(0,3);foreach(string part in p.Substring(3).Split('\\')){current=current.TrimEnd('\\')+"\\"+part;if(!Engine.Exists(current)&&!CreateDirectoryW(Engine.NativePath(current),IntPtr.Zero))throw new Exception("CreateDirectory failed");}}
 static void WriteNative(string p){IntPtr h=CreateFileW(Engine.NativePath(p),0x40000000,0,IntPtr.Zero,2,128,IntPtr.Zero);if(h==new IntPtr(-1))throw new Exception("CreateFile failed");CloseHandle(h);}
 static void RegistryTests(){string name="JingChuTest_"+Guid.NewGuid().ToString("N"),path="SOFTWARE\\"+name;var view=Environment.Is64BitOperatingSystem?RegistryView.Registry64:RegistryView.Registry32;var item=new RegItem{Hive=RegistryHive.CurrentUser,View=view,Path=path,Description="isolated self-test"};string uninstall=@"SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall\"+name;
  using(var baseKey=RegistryKey.OpenBaseKey(RegistryHive.CurrentUser,view))try{
   using(var k=baseKey.CreateSubKey(path)){k.SetValue("Text","中文 test");k.SetValue("Count",7,RegistryValueKind.DWord);using(var sub=k.CreateSubKey("Nested"))sub.SetValue("Keep","yes");}
   string backup=Engine.Backup(item);Check(File.Exists(backup)&&new FileInfo(backup).Length>50,"registry export backup");
   Engine.RemoveRegistry(item);using(var k=baseKey.OpenSubKey(path))Check(k==null,"backed-up registry deletion");
   Engine.Restore(backup);using(var k=baseKey.OpenSubKey(path))Check(Convert.ToInt32(k.GetValue("Count"))==7&&Convert.ToString(k.GetValue("Text"))=="中文 test","registry restore types and Unicode");
   Check(Engine.ScanRegistry(name).Any(x=>x.Path==path),"registry residual name matching");
   string marker=Path.Combine(root,"uninstall-marker.txt");string command=Engine.Quote(Application.ExecutablePath)+" /stub "+Engine.Quote(marker);
   using(var k=baseKey.CreateSubKey(uninstall)){k.SetValue("DisplayName",name);k.SetValue("UninstallString",command);k.SetValue("DisplayVersion","1.0-test");k.SetValue("DisplayIcon",Engine.Quote(Application.ExecutablePath)+",0");}
   var app=Engine.Apps().First(x=>x.Name==name);Check(app.Command==command,"installed app enumeration");Check(app.IconSpec==Engine.Quote(Application.ExecutablePath)+",0","installed app DisplayIcon metadata");
   using(var p=Engine.Uninstall(app)){if(p!=null)Check(Engine.WaitForUninstall(p,CancellationToken.None)==0,"uninstaller exit is awaited before scan");}Check(File.Exists(marker),"uninstall launches registered executable and arguments");Check(Engine.UninstallEntryExists(app),"unfinished uninstall registration is detected");var residual=Engine.ScanAfterUninstall(app,CancellationToken.None);Check(residual.Any(r=>r.Path==path)&&residual.Any(r=>r.Path==uninstall),"post-uninstall registry scan lists candidates");using(var k=baseKey.OpenSubKey(path))Check(Convert.ToInt32(k.GetValue("Count"))==7,"post-uninstall scan leaves registry unchanged");
   Check(Engine.ScanRegistry(name).Any(x=>x.Path==uninstall),"uninstall residual matching");
   Reject(()=>Engine.RemoveRegistry(new RegItem{Hive=RegistryHive.CurrentUser,View=view,Path="SOFTWARE\\Microsoft"}),"protected registry key blocked");
   Reject(()=>Engine.ScanRegistry("ab"),"short residual keyword rejected");
   Check(Engine.Startup()!=null,"startup registry enumeration");
   if(Environment.Is64BitOperatingSystem){var item32=new RegItem{Hive=RegistryHive.CurrentUser,View=RegistryView.Registry32,Path="SOFTWARE\\"+name+"_32"};using(var b32=RegistryKey.OpenBaseKey(RegistryHive.CurrentUser,RegistryView.Registry32))try{using(var k=b32.CreateSubKey(item32.Path))k.SetValue("View",32);string f=Engine.Backup(item32);Engine.RemoveRegistry(item32);Engine.Restore(f);using(var k=b32.OpenSubKey(item32.Path))Check(Convert.ToInt32(k.GetValue("View"))==32,"32-bit registry backup and restore view");}finally{b32.DeleteSubKeyTree(item32.Path,false);}}
  }finally{baseKey.DeleteSubKeyTree(path,false);baseKey.DeleteSubKeyTree(uninstall,false);}
 }
 static void InstallerTest(){string dir=Dir("installed"),menu=Dir("test-menu"),desktop=Path.Combine(root,"test-desktop.lnk"),key="SOFTWARE\\JingChuSetupTest_"+Guid.NewGuid().ToString("N");AppDomain.CurrentDomain.SetData("JingChu.SetupTestReg",key);AppDomain.CurrentDomain.SetData("JingChu.SetupTestMenu",menu);AppDomain.CurrentDomain.SetData("JingChu.SetupTestDesktop",desktop);
  try{Type setup=typeof(JingSetup.Program);var install=setup.GetMethod("Install",BindingFlags.NonPublic|BindingFlags.Static);install.Invoke(null,new object[]{dir,true});Check(File.Exists(Path.Combine(dir,"JingChu.exe"))&&File.Exists(Path.Combine(dir,"Uninstall.exe")),"installer extracts app and standalone uninstaller");Check(File.ReadAllBytes(Path.Combine(dir,"JingChu.exe")).SequenceEqual(File.ReadAllBytes(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"JingChu.exe"))),"installer embedded payload matches portable executable");Check(File.Exists(desktop)&&File.Exists(Path.Combine(menu,"景·除.lnk")),"installer creates shortcuts");using(var k=Registry.CurrentUser.OpenSubKey(key))Check(Convert.ToString(k.GetValue("InstallLocation"))==dir,"installer creates current-user uninstall registration");
   File.WriteAllText(Path.Combine(dir,"user-file.txt"),"preserve unknown files");using(var p=Process.Start(new ProcessStartInfo(Path.Combine(dir,"Uninstall.exe"),"/remove-stub "+Engine.Quote(root)+" "+Engine.Quote(key)){UseShellExecute=false,CreateNoWindow=true})){if(!p.WaitForExit(15000)||p.ExitCode!=0)throw new Exception("Uninstall subprocess failed");}
   Check(!File.Exists(Path.Combine(dir,"JingChu.exe"))&&!File.Exists(desktop),"uninstaller removes app and shortcuts");using(var k=Registry.CurrentUser.OpenSubKey(key))Check(k==null,"uninstaller removes uninstall registration");
   for(int i=0;i<100&&File.Exists(Path.Combine(dir,"Uninstall.exe"));i++)Thread.Sleep(100);
   Check(!File.Exists(Path.Combine(dir,"Uninstall.exe")),"uninstaller cleans itself after exiting");Check(File.Exists(Path.Combine(dir,"user-file.txt")),"uninstaller preserves unknown files");
   using(var form=(Form)Activator.CreateInstance(setup.GetNestedType("SetupForm",BindingFlags.NonPublic))){form.Show();Application.DoEvents();using(var bitmap=new Bitmap(form.Width,form.Height)){form.DrawToBitmap(bitmap,new Rectangle(0,0,form.Width,form.Height));bitmap.Save(Path.Combine(root,"installer.png"));}form.Close();Check(true,"installer UI renders");}
  }
  finally{Registry.CurrentUser.DeleteSubKeyTree(key,false);}
 }
 static void UiTest(){Application.EnableVisualStyles();using(var f=new MainForm()){f.Show();Application.DoEvents();PopulateIconPreview(f);PopulateStartupPreview(f);PopulateResiduePreview(f);MenuTests(f);CheckboxTests(f);var page=f.GetType().GetMethod("ShowPage",BindingFlags.Instance|BindingFlags.NonPublic);for(int i=0;i<8;i++){page.Invoke(f,new object[]{i});Application.DoEvents();using(var bitmap=new Bitmap(f.Width,f.Height)){f.DrawToBitmap(bitmap,new Rectangle(0,0,f.Width,f.Height));bitmap.Save(Path.Combine(root,"page-"+i+".png"));}}Check(f.Controls.Count>0,"eight UI pages render");f.Size=f.MinimumSize;page.Invoke(f,new object[]{4});Application.DoEvents();using(var bitmap=new Bitmap(f.Width,f.Height)){f.DrawToBitmap(bitmap,new Rectangle(0,0,f.Width,f.Height));bitmap.Save(Path.Combine(root,"page-minimum.png"));}Check(f.Width>=1160,"minimum window layout renders");f.Close();}}
 static void LogoTest(){using(var logo=new Bitmap(Look.Logo))Check(logo.GetPixel(0,0).A==0,"transparent logo asset embedded");}
 static void CheckboxTests(MainForm f){var type=typeof(MainForm);var view=(ListView)type.GetField("apps",BindingFlags.Instance|BindingFlags.NonPublic).GetValue(f);var search=(TextBox)type.GetField("search",BindingFlags.Instance|BindingFlags.NonPublic).GetValue(f);var targets=type.GetMethod("UninstallTargets",BindingFlags.Instance|BindingFlags.NonPublic);f.ShowPage(2);Application.DoEvents();Check(view.CheckBoxes,"uninstall list provides checkboxes");view.Items[0].Checked=true;view.Items[1].Checked=true;Check(((System.Collections.Generic.List<InstalledApp>)targets.Invoke(f,null)).Count==2,"checked apps form the uninstall queue");search.Text="不存在的搜索结果";Check(view.Items.Count==0&&((System.Collections.Generic.List<InstalledApp>)targets.Invoke(f,null)).Count==2,"checked software survives search filtering");search.Text="";Check(view.CheckedItems.Count==2,"checkboxes restored when search is cleared");var entries=(System.Collections.Generic.List<InstalledApp>)type.GetField("installed",BindingFlags.Instance|BindingFlags.NonPublic).GetValue(f);type.GetMethod("SetInstalledApps",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(f,new object[]{entries,entries.Select(SoftwareIcons.Load).ToList()});Check(view.CheckedItems.Count==2,"checkboxes retained through list refresh");foreach(ListViewItem r in view.Items)r.Checked=false;view.Items[2].Selected=true;Check(((System.Collections.Generic.List<InstalledApp>)targets.Invoke(f,null)).Count==1,"row selection fallback works when nothing is checked");view.Items[2].Selected=false;
  using(var dialog=BrandDialogs.Create("测试提示内容","软件列表",MessageBoxButtons.OKCancel)){using(var actual=dialog.Icon.ToBitmap())using(var expected=Icon.ExtractAssociatedIcon(Application.ExecutablePath).ToBitmap())Check(Signature(actual)==Signature(expected),"message dialog title icon uses product logo");dialog.Show();Application.DoEvents();using(var b=new Bitmap(dialog.Width,dialog.Height)){dialog.DrawToBitmap(b,new Rectangle(Point.Empty,b.Size));b.Save(Path.Combine(root,"brand-dialog.png"));}dialog.Close();}using(var popup=new Form()){BrandDialogs.ApplyIcon(popup);Check(popup.ShowIcon&&popup.Icon!=null,"custom popup branding supplies logo icon");}
 }
 static void MenuTests(MainForm f){Func<string,ListView> get=name=>(ListView)typeof(MainForm).GetField(name,BindingFlags.NonPublic|BindingFlags.Instance).GetValue(f);foreach(string name in new[]{"files","apps","residue","smart","startup","backups"})Check(get(name).ContextMenuStrip!=null&&get(name).ContextMenuStrip.Items.Count>=5,"context menu attached: "+name);f.ShowPage(2);Application.DoEvents();var apps=get("apps");apps.Items[0].Selected=true;apps.Items[1].Selected=true;Check(apps.MultiSelect&&apps.SelectedItems.Count==2,"software list supports multiple selected rows");var a=new InstalledApp{Name="App A",Command="a.exe"};var b=new InstalledApp{Name="App B",Command="b.exe"};var duplicate=new InstalledApp{Name="App A",Command="a.exe"};var queue=Engine.PrepareUninstallQueue(new[]{a,b,duplicate});Check(queue.Count==2&&queue[0]==a&&queue[1]==b,"uninstall queue preserves order and deduplicates registrations");f.ShowPage(1);Application.DoEvents();var files=get("files");files.Items.Add(new ListViewItem("context one"){Checked=true});files.Items.Add(new ListViewItem("context two"){Checked=true});files.Items[0].Selected=true;typeof(MainForm).GetMethod("CheckSelection",BindingFlags.NonPublic|BindingFlags.Static).Invoke(null,new object[]{files});Check(files.CheckedItems.Count==1&&files.Items[0].Checked,"context action targets selected rows without including other checked rows");files.Items.Clear();foreach(ListViewItem row in apps.SelectedItems.Cast<ListViewItem>().ToArray())row.Selected=false;}
 static void PopulateResiduePreview(MainForm f){Check(Engine.ResidualName("豆包 2.0")=="豆包","short Chinese product name normalization");Check(Engine.ScanAfterUninstall(new InstalledApp{Name="豆包"},CancellationToken.None)!=null,"short product names use exact registry matching");Check(Engine.ResidualName("Example App 12.3.4 (x64)")=="Example App","automatic residual keyword strips version");Reject(()=>Engine.WaitForUninstall(null,CancellationToken.None),"missing uninstaller process requires manual scan");string marker=Path.Combine(root,"delayed-marker.txt");using(var p=Process.Start(new ProcessStartInfo(Application.ExecutablePath,"/delayed-stub "+Engine.Quote(marker)){UseShellExecute=false,CreateNoWindow=true})){var cancel=new CancellationTokenSource();cancel.Cancel();Reject(()=>Engine.WaitForUninstall(p,cancel.Token),"cancel stops waiting for automatic scan");p.WaitForExit(5000);Check(File.Exists(marker),"cancel does not kill the external uninstaller");}
  var app=new InstalledApp{Name="Example App 12.3.4 (x64)"};var rows=new System.Collections.Generic.List<RegItem>{new RegItem{Hive=RegistryHive.CurrentUser,View=RegistryView.Registry64,Path=@"SOFTWARE\Example App",Description="隔离界面示例"}};typeof(MainForm).GetMethod("ShowUninstallResidues",BindingFlags.NonPublic|BindingFlags.Instance).Invoke(f,new object[]{app,rows});var view=(ListView)typeof(MainForm).GetField("residue",BindingFlags.NonPublic|BindingFlags.Instance).GetValue(f);Check(view.Items.Count==1&&view.CheckedItems.Count==0&&view.Items[0].Tag==rows[0],"automatic results require explicit user selection before deletion");}
