 static void StartupIconTests(){string exe=Application.ExecutablePath;var reg=new RegItem{ValueName="注册表程序示例",Description=Engine.Quote(exe)+" --startup"};using(var image=SoftwareIcons.Startup(reg))using(var expected=SoftwareIcons.ReadSpec(exe))Check(Signature(image)==Signature(expected),"Run command executable icon");
  string active=Path.Combine(Engine.StartupUser,"真实快捷方式图标.lnk"),disabled=Path.Combine(Engine.StartupUser,"已禁用快捷方式图标.lnk");var create=typeof(JingSetup.Program).GetMethod("Shortcut",BindingFlags.NonPublic|BindingFlags.Static);create.Invoke(null,new object[]{active,exe,""});create.Invoke(null,new object[]{disabled,exe,""});var a=Engine.StartupFiles().First(x=>x.Path==active);var b=Engine.StartupFiles().First(x=>x.Path==disabled);using(var image=SoftwareIcons.Startup(a))using(var expected=SoftwareIcons.ReadSpec(exe))Check(Signature(image)==Signature(expected),"startup shortcut resolves target icon without executing it");Engine.DisableStartupFile(b);b=Engine.StartupFiles().First(x=>x.Path==disabled&&x.Disabled);using(var image=SoftwareIcons.Startup(b))using(var expected=SoftwareIcons.ReadSpec(exe))Check(Signature(image)==Signature(expected),"disabled shortcut payload preserves target icon");
