  using(var image=SoftwareIcons.Startup(new StartupFile{Name="missing.lnk",Path=Path.Combine(root,"missing.lnk")}))using(var expected=SoftwareIcons.Fallback())Check(Signature(image)==Signature(expected),"invalid shortcut safely gets fallback icon");startupPreview=new object[]{reg,a,b};
