 static void PopulateStartupPreview(MainForm f){var rows=startupPreview.Select((x,i)=>new ListViewItem(new[]{i==0?"注册表启动项图标示例":i==1?"快捷方式图标示例":"已禁用快捷方式图标示例","隔离测试项目",i==2?"已禁用":"启用中"}){Tag=x}).ToList();var setter=typeof(MainForm).GetMethod("SetStartupRows",BindingFlags.NonPublic|BindingFlags.Instance);setter.Invoke(f,new object[]{rows,startupPreview.Select(SoftwareIcons.Startup).ToList()});var view=(ListView)typeof(MainForm).GetField("startup",BindingFlags.NonPublic|BindingFlags.Instance).GetValue(f);Check(view.Items.Count==3&&view.Items.Cast<ListViewItem>().All(x=>x.ImageIndex>=0),"startup rows bind icons for all three item types");rows=rows.Select(x=>(ListViewItem)x.Clone()).ToList();setter.Invoke(f,new object[]{rows,startupPreview.Select(SoftwareIcons.Startup).ToList()});Check(view.SmallImageList.Images.Count==3,"startup refresh replaces icon resources");}
 class PaintProbe:SoftButton{public void DrawOnly(Bitmap image){using(var g=Graphics.FromImage(image)){g.Clear(Color.Magenta);OnPaint(new PaintEventArgs(g,new Rectangle(Point.Empty,image.Size)));}}public void Hover(){OnMouseEnter(EventArgs.Empty);}}
 static bool CornersMatch(Bitmap b,Color c){return new[]{new Point(0,0),new Point(b.Width-1,0),new Point(0,b.Height-1),new Point(b.Width-1,b.Height-1)}.All(p=>b.GetPixel(p.X,p.Y).ToArgb()==c.ToArgb());}
 static void ButtonPaintTests(){using(var host=new FlowLayoutPanel{BackColor=Look.Canvas,Size=new Size(500,200)})using(var b=new PaintProbe{Text="测试按钮",Size=new Size(120,38)}){host.Controls.Add(b);for(int mode=0;mode<5;mode++){b.Primary=mode==1;b.Danger=mode==2;b.Enabled=mode!=3;if(mode==4)b.Hover();using(var bitmap=new Bitmap(b.Width,b.Height)){b.DrawOnly(bitmap);Check(CornersMatch(bitmap,Look.Canvas),"button paint covers corners without native background, state "+mode);}}b.Enabled=true;b.Size=new Size(190,57);using(var bitmap=new Bitmap(b.Width,b.Height)){b.DrawOnly(bitmap);Check(CornersMatch(bitmap,Look.Canvas),"scaled button corner background");}}
  using(var host=new Panel{BackColor=Look.Canvas,Size=new Size(400,200)})using(var card=new CardPanel{Dark=true,Size=new Size(350,170)}){host.Controls.Add(card);using(var parent=new Bitmap(card.Width,card.Height)){card.DrawToBitmap(parent,new Rectangle(Point.Empty,parent.Size));using(var b=new PaintProbe{Text="卡片按钮",Location=new Point(30,70),Size=new Size(130,38)}){card.Controls.Add(b);using(var image=new Bitmap(b.Width,b.Height)){b.DrawOnly(image);Check(image.GetPixel(0,0).ToArgb()==parent.GetPixel(b.Left,b.Top).ToArgb(),"button gradient parent background preserved");}}}}
 }
 static long Signature(Bitmap b){long n=17;unchecked{for(int y=0;y<b.Height;y++)for(int x=0;x<b.Width;x++)n=n*31+b.GetPixel(x,y).ToArgb();}return n;}
 static void IconTests(){string path;int index;SoftwareIcons.Parse("\"C:\\Program Files\\A,B\\product.exe\",-12",out path,out index);Check(path==@"C:\Program Files\A,B\product.exe"&&index==-12,"DisplayIcon quoted comma path and negative resource index");SoftwareIcons.Parse(@"%SystemRoot%\System32\shell32.dll,0",out path,out index);Check(path==Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.Windows),@"System32\shell32.dll")&&index==0,"DisplayIcon environment expansion");
  string exe=Application.ExecutablePath;using(var icon=SoftwareIcons.ReadSpec(Engine.Quote(exe)+",0")){Check(icon!=null&&icon.Size==new Size(32,34),"executable icon extraction");var a=new InstalledApp{Name="Fallback executable",Command=Engine.Quote(exe)+" /nothing",IconSpec=Path.Combine(root,"missing.ico")};using(var fallback=SoftwareIcons.Load(a))Check(Signature(icon)==Signature(fallback),"missing DisplayIcon falls back to program executable");}
  string ico=Path.GetFullPath(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,@"..\app.ico"));using(var image=SoftwareIcons.ReadSpec(ico))Check(image!=null,"ICO file extraction");Check(SoftwareIcons.ReadSpec(Path.Combine(root,"absent.exe"))==null,"missing icon source safely returns no image");using(var generic=SoftwareIcons.Load(new InstalledApp{Name="Missing"}))using(var expected=SoftwareIcons.Fallback())Check(Signature(generic)==Signature(expected),"software with no icon uses default graphic");
  string location=Dir("icon-install");File.Copy(exe,Path.Combine(location,"Product.exe"));using(var image=SoftwareIcons.Load(new InstalledApp{Name="Product",Location=location}))using(var expected=SoftwareIcons.ReadSpec(exe))Check(Signature(image)==Signature(expected),"product install-directory icon fallback");
 }
 static void PopulateIconPreview(MainForm f){var entries=new System.Collections.Generic.List<InstalledApp>{new InstalledApp{Name="景·除 · 图标显示示例",IconSpec=Application.ExecutablePath,Version="2.0.1",Publisher="本地测试",Command=""},new InstalledApp{Name="系统程序图标示例",IconSpec=Path.Combine(Environment.SystemDirectory,"notepad.exe"),Publisher="本地测试",Command=""},new InstalledApp{Name="缺失图标 · 默认图形示例",Publisher="本地测试",Command=""}};var setter=typeof(MainForm).GetMethod("SetInstalledApps",BindingFlags.NonPublic|BindingFlags.Instance);setter.Invoke(f,new object[]{entries,entries.Select(SoftwareIcons.Load).ToList()});var view=(ListView)typeof(MainForm).GetField("apps",BindingFlags.NonPublic|BindingFlags.Instance).GetValue(f);Check(view.SmallImageList.Images.Count==3&&view.Items.Cast<ListViewItem>().All(x=>x.ImageIndex>=0),"software rows have actual image-list indexes");var search=(TextBox)typeof(MainForm).GetField("search",BindingFlags.NonPublic|BindingFlags.Instance).GetValue(f);search.Text="景·除";Check(view.Items.Count==1&&view.Items[0].ImageIndex==0,"software filtering preserves icon association");search.Text="";setter.Invoke(f,new object[]{entries,entries.Select(SoftwareIcons.Load).ToList()});Check(view.Items.Count==3&&view.SmallImageList.Images.Count==3,"software refresh rebuilds icon list");}
 static void ExtraTests(){string scan=Dir("cleanup-scan"),old=Path.Combine(scan,"old.tmp"),recent=Path.Combine(scan,"recent.tmp"),big=Path.Combine(scan,"big.bin"),zero=Path.Combine(scan,"zero.txt");File.WriteAllText(old,"old temporary");File.SetLastWriteTimeUtc(old,DateTime.UtcNow.AddDays(-20));File.WriteAllText(recent,"recent");File.WriteAllBytes(big,new byte[256]);File.WriteAllBytes(zero,new byte[0]);string empty=Path.Combine(scan,"empty"),another=Path.Combine(scan,"another-empty");Directory.CreateDirectory(empty);Directory.CreateDirectory(another);
  string keep=Dir("scan-link-target");File.WriteAllText(Path.Combine(keep,"invisible.tmp"),"old");File.SetLastWriteTimeUtc(Path.Combine(keep,"invisible.tmp"),DateTime.UtcNow.AddDays(-20));string link=Path.Combine(scan,"link"),output;Check(Engine.Run(Environment.GetEnvironmentVariable("ComSpec"),"/c mklink /J "+Engine.Quote(link)+" "+Engine.Quote(keep),out output)==0,"cleanup link fixture");
  var aged=Engine.ScanCleanup(scan,0,7,100,CancellationToken.None,x=>{});Check(aged.Items.Count==1&&aged.Items[0].Path==old,"temporary scan respects age and skips linked targets");
  var large=Engine.ScanCleanup(scan,2,7,100,CancellationToken.None,x=>{});Check(large.Items.Count==1&&large.Items[0].Path==big,"large file threshold scan");
  var zeros=Engine.ScanCleanup(scan,3,7,100,CancellationToken.None,x=>{});Check(zeros.Items.Count==1&&zeros.Items[0].Path==zero,"zero-byte file scan");
  var dirs=Engine.ScanCleanup(scan,1,7,100,CancellationToken.None,x=>{});Check(dirs.Items.Count==2&&dirs.Items.All(x=>x.Path!=scan),"empty folder scan excludes scan root");
  File.WriteAllText(Path.Combine(empty,"new.txt"),"preserve");Reject(()=>Engine.DeleteCandidate(dirs.Items.First(x=>x.Path==empty),false,CancellationToken.None),"empty folder recheck protects new files");Check(File.Exists(Path.Combine(empty,"new.txt")),"new file survives empty cleanup");Engine.DeleteCandidate(dirs.Items.First(x=>x.Path==another),false,CancellationToken.None);Check(!Directory.Exists(another),"empty directory removal");
  string preview=Engine.Preview(new[]{old},CancellationToken.None);Check(preview.Contains(old)&&File.Exists(old),"delete preview is non-mutating");Engine.DeleteCandidate(aged.Items[0],false,CancellationToken.None);Check(!File.Exists(old)&&File.Exists(recent),"aged cleanup preserves recent files");
  File.AppendAllText(big,"changed");Reject(()=>Engine.DeleteCandidate(large.Items[0],false,CancellationToken.None),"changed file skipped before cleanup");Check(File.Exists(big),"changed file remains");Engine.DeleteCandidate(zeros.Items[0],false,CancellationToken.None);Check(!File.Exists(zero),"zero-byte cleanup");
  var stop=new CancellationTokenSource();stop.Cancel();Reject(()=>Engine.ScanCleanup(scan,2,7,100,stop.Token,x=>{}),"cleanup scan cancellation");Reject(()=>Engine.ScanCleanup(link,0,7,100,CancellationToken.None,x=>{}),"directory link scan root rejected");
  string csv=Path.Combine(root,"export.csv");Engine.ExportCsv(csv,new[]{"路径","说明"},new[]{new[]{"中文,\"file\"","=formula"}});string exported=File.ReadAllText(csv);Check(exported.Contains("中文,\"\"file\"\"")&&exported.Contains("'=formula"),"CSV quotes Unicode and neutralizes formula prefix");
  string user=Dir("startup-user"),common=Dir("startup-common");AppDomain.CurrentDomain.SetData("JingChu.TestStartupUser",user);AppDomain.CurrentDomain.SetData("JingChu.TestStartupCommon",common);string startup=Path.Combine(user,"sample.lnk");File.WriteAllText(startup,"shortcut test payload");var sf=Engine.StartupFiles().First(x=>x.Path==startup);Check(!sf.Disabled,"startup-folder file enumeration");Engine.DisableStartupFile(sf);var disabled=Engine.StartupFiles().First(x=>x.Path==startup&&x.Disabled);Check(!File.Exists(startup)&&File.Exists(disabled.Payload),"startup file disabled with retained backup");Engine.EnableStartupFile(disabled);Check(File.ReadAllText(startup)=="shortcut test payload"&&!File.Exists(disabled.Payload),"startup file restored from backup");
  sf=Engine.StartupFiles().First(x=>x.Path==startup);Engine.DisableStartupFile(sf);disabled=Engine.StartupFiles().First(x=>x.Path==startup&&x.Disabled);File.WriteAllText(startup,"new original");Reject(()=>Engine.EnableStartupFile(disabled),"startup restore never overwrites new same-name file");Check(File.ReadAllText(startup)=="new original"&&File.Exists(disabled.Payload),"startup conflict preserves both copies");
  string readonlyFile=Path.Combine(user,"readonly.lnk");File.WriteAllText(readonlyFile,"test");File.SetAttributes(readonlyFile,FileAttributes.ReadOnly);int count=Directory.GetFiles(Engine.StartupDisabled,"*.meta").Length;Reject(()=>Engine.DisableStartupFile(Engine.StartupFiles().First(x=>x.Path==readonlyFile&&!x.Disabled)),"readonly startup disable reports failure");Check(Directory.GetFiles(Engine.StartupDisabled,"*.meta").Length==count&&File.Exists(readonlyFile),"failed startup disable leaves no false disabled receipt");File.SetAttributes(readonlyFile,FileAttributes.Normal);

